def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([1]), fmt([10**9]), fmt([5, 5]), fmt([2, 2, 2, 2]), fmt([1, 2, 3, 4, 5]), fmt([5, 4, 3, 2, 1]), fmt([3, 1, 2, 4])]
    for n in (2, 3, 4, 6, 8, 10, 15, 20):
        for hi in (3, 10, 10**9):
            tests.append(fmt([rng.randint(1, hi) for _ in range(n)]))
    N = 100000
    tests.append(fmt([rng.randint(1, 10**9) for _ in range(N)]))
    tests.append(fmt([10**9] * N))
    tests.append(fmt([10**9 - i for i in range(N)]))
    tests.append(fmt([rng.randint(1, 3) for _ in range(N)]))
    tests.append(fmt(list(range(1, N + 1))))
    return tests
